def _state_bytes(s):
    out = bytearray()
    _enc(s.w, ('n',), out)
    _enc(s.nj, ('n',), out)
    _enc(s.st.d, ('n',), out)
    _enc(len(s.st.m), ('n',), out)
    for k, v in sorted(s.st.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    _enc(s.tries.d, ('n',), out)
    _enc(len(s.tries.m), ('n',), out)
    for k, v in sorted(s.tries.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    _enc(sorted(s.Q), ('l', ('n',)), out)
    _enc(s.slots, ('n',), out)
    _enc(s.entered.d, ('n',), out)
    _enc(len(s.entered.m), ('n',), out)
    for k, v in sorted(s.entered.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    _enc(s.byTries.d, ('n',), out)
    _enc(len(s.byTries.m), ('n',), out)
    for k, v in sorted(s.byTries.m.items()):
        _enc(k, ('n',), out)
        _enc(v, ('n',), out)
    return bytes(out)


def _stepper_init(s, audit):
    s._audit = audit
    _AUDIT[0] = audit
    s._d_Job = []
    s.st.w = s._d_Job
    s.tries.w = s._d_Job
    s._ix_retryable = _Index(3, 1)
    s._aud_retryable = []
    s._ix_spent = _Index(0, 1)
    s._aud_spent = []
    for v in range(_ixbound_retryable(s)):
        _ixrefresh_retryable(s, v)
    for v in range(_ixbound_spent(s)):
        _ixrefresh_spent(s, v)
    if audit:
        _audit(s)


def _loop(s, out):
    """The output loop (docs/spec.md §3.8.3): the first enabled output in
    policy order, until none is."""
    n = 0
    while True:
        for f in _OUTS:
            if f(s, out):
                break
        else:
            return
        _refresh(s)
        n += 1
        if n >= 1 << 24:
            raise StepLimit("2^24 actions in one step")


class State:
    """The stepper of the refined Core (docs/spec.md §3.8.1, §3.8.2, §3.12.2).
    With audit, every index is checked against its definition after every
    summand (§3.9.9): tests only."""

    __slots__ = ("_s",)

    def __init__(self, config, out, audit=False):
        s = _initial(config)
        _stepper_init(s, audit)
        self._s = s
        _loop(s, out)

    def step(self, event, out):
        s = self._s
        for match, fire in _STEP.get(event[0], ()):
            env = match(s, event[1:])
            if env is not None:
                fire(s, env)
                _refresh(s)
                _loop(s, out)
                return
        raise Refused(event)

    def bytes(self):
        """An estimate of the memory the state holds (§3.13.4)."""
        n = 0
        for name in _S.__slots__:
            v = getattr(self._s, name, None)
            if isinstance(v, _Col):
                n += 16 * len(v.m)
            elif isinstance(v, (tuple, frozenset, list)):
                n += 8 * len(v)
            else:
                n += 8
        return n

    def state_bytes(self):
        """Every parameter's value, encoded as entries are (for comparing the backends)."""
        return _state_bytes(self._s)

    def read(self, name):
        """A parameter's value (a stored function as a view)."""
        return getattr(self._s, name)
